def build():
    rows = json.loads((PROJECT/'reports/sentence_residue_candidates.json').read_text(encoding='utf-8'))
    targets = {}
    for line in REVIEWED.splitlines():
        key,value = line.split('\t',1)
        targets[int(key)] = value.replace(r'\n','\n')
    if set(targets) != set(range(len(rows))):
        raise ValueError('Unexpected baseline or missing review')
    mapping = {rows[i]['source']:t for i,t in targets.items()}
    from build import check_translation
    errors = [{'source':s,'translation':t,'issues':check_translation(s,t)} for s,t in mapping.items() if check_translation(s,t)]
    (PROJECT/'source/manual_remaining_sentences.json').write_text(json.dumps(mapping,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    report={'reviewed_unique_sources':len(mapping),'structural_errors':errors,'reviewer':'ChatGPT; full-source review of each selected residue candidate'}
    (PROJECT/'reports/remaining_sentence_review.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(json.dumps(report,ensure_ascii=False,indent=2))
    if errors:
        raise SystemExit(1)


if __name__ == '__main__':
    build()
